{"path": "app.js", "offset_utf8_bytes": 48376, "content": "(o.type === 'store') return storeDrawer();
    if (o.type === 'media') return mediaModal(o);
    if (o.type === 'parts') return partsModal(o);
    if (o.type === 'added') return addedPanel(o);
    if (o.type === 'reviews') return reviewsModal(o);
    return '';
  }

  function closeIcon() { return '<button class="iconbtn" data-act="close-overlay" aria-label="Close">' + I.close + '</button>'; }
  function ovWrap(inner, center) {
    return '<div class="ov' + (center ? ' center' : '') + '" data-act="ov-bg">' + inner + '</div>';
  }
  var checkGreen = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="#0a8a00" stroke-width="2.6"><path d="M5 12.5l4.5 4.5L19 7"/></svg>';

  /* ---------- ZIP / location drawer ---------- */
  function locationDrawer() {
    var cls = 'zipin' + (UI.zipOk ? ' ok' : (UI.zipErr ? ' err' : ''));
    var help = UI.zipErr
      ? '<div class="ziperr">' + I.info + ' ' + esc(UI.zipErr) + '</div>'
      : (UI.zipOk ? '<div class="ziphelp ok">' + checkGreen + ' e.g. 19428</div>' : '<div class="ziphelp">e.g. 19428</div>');
    return ovWrap('<aside class="drawer">' +
      '<div class="dh"><div></div>' + closeIcon() + '</div>' +
      '<div class="db">' +
        '<h2>Use your location</h2>' +
        '<p style="font-size:14px;margin-bottom:24px">Get updated information about product delivery and stock availability for your area.</p>' +
        '<div class="ziplbl"><span class="req">*</span> Enter a Zip code</div>' +
        '<input id="zipInput" class="' + cls + '" value="' + esc(UI.zipVal) + '" maxlength="5" autocomplete="off" inputmode="numeric">' +
        help +
        '<p style="font-size:14px;margin-top:32px;color:#333">We use cookies to provide this service. Read more about how we use cookies in ' +
        '<a style="text-decoration:underline">our policy</a> <span style="display:inline-block;width:13px;height:13px;border:1px solid #767676;vertical-align:-2px"></span>. ' +
        'Please note that your location won\u2019t be shared.</p>' +
      '</div>' +
      '<div class="df"><button class="btn black full" data-act="save-zip">Save</button></div>' +
      '</aside>');
  }

  /* ---------- store drawer ---------- */
  function storeDrawer() {
    var f = UI.storeFilter || '';
    var list = STORES.filter(function (s) {
      return !f || (s[0] + ' ' + s[1]).toLowerCase().indexOf(f.toLowerCase()) >= 0;
    });
    return ovWrap('<aside class="drawer wide">' +
      '<div class="dh"><div></div>' + closeIcon() + '</div>' +
      '<div class="db">' +
        '<h2>Select store</h2>' +
        '<p style="font-size:14px;margin-bottom:20px">Find your preferred store to learn about its opening hours, stock availability, and relevant offers.</p>' +
        '<div style="display:flex;align-items:center;gap:10px;background:#f5f5f5;border-radius:100px;height:48px;padding:0 16px">' + I.search +
          '<input id="storeSearch" placeholder="Search by location" value="' + esc(f) + '" style="border:0;outline:0;background:transparent;flex:1;font-size:15px">' +
        '</div>' +
        '<div class="storelist">' + list.map(function (s) {
          var on = ST.location.store === s[0];
          return '<button class="' + (on ? 'on' : '') + '" data-act="select-store" data-store="' + esc(s[0]) + '">' +
            '<div class="n">' + esc(s[0]) + '</div><div class="a">' + esc(s[1]) + '</div></button>';
        }).join('') + '</div>' +
      '</div></aside>');
  }

  /* ---------- media modal ---------- */
  function mediaModal(o) {
    var p = P(o.id);
    if (!p) return '';
    var gal = p.gallery || [p.image];
    var tabs = [['all', 'All media'], ['video', 'Video'], ['measurement', 'Measurement']];
    var body;
    if (UI.mediaTab === 'measurement') {
      body = '<div style="padding:0 30px"><img src="/assets/media-317.jpg" style="width:100%;background:#f5f5f5"></div>';
    } else if (UI.mediaTab === 'video') {
      var v = gal[1] || gal[0];
      body = '<div style="padding:0 30px"><div style="position:relative;background:#f5f5f5">' +
        '<img src="' + v + '" style="width:100%">' +
        '<span style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:58px;height:58px;border-radius:50%;background:rgba(0,0,0,.62);color:#fff;display:flex;align-items:center;justify-content:center;font-size:18px">\u25B6</span>' +
        '</div></div>';
    } else {
      body = '<div class="mgrid">' + gal.map(function (g) { return '<img src="' + g + '">'; }).join('') + '</div>';
    }
    return ovWrap('<div class="modal media">' +
      '<div class="mh">' + closeIcon() + '</div>' +
      '<div class="mb">' +
        '<div class="mtags">' + tabs.map(function (t) {
          return '<button class="' + (UI.mediaTab === t[0] ? 'on' : '') + '" data-act="media-tab" data-tab="' + t[0] + '">' + t[1] + '</button>';
        }).join('') + '</div>' + body +
      '</div></div>', true);
  }

  /* ---------- "What's included" parts modal ---------- */
  function partsModal(o) {
    var p = P(o.id);
    if (!p || !p.components) return '';
    var mult = o.qty || 1;
    var rows = p.components.map(function (c) {
      return '<div style="border-bottom:1px solid var(--line2);padding:18px 0">' +
        '<div style="font-weight:700;font-size:14px">' + esc(c.name) + '</div>' +
        '<div style="font-size:14px">' + esc(c.type) + (c.desc ? ', ' + esc(c.desc) : '') + '</div>' +
        '<div style="font-size:14px;color:#484848;margin-top:2px">Quantity: ' + (c.qty * mult) + '</div></div>';
    }).join('');
    return ovWrap('<aside class="drawer wide">' +
      '<div class="dh"><div></div>' + closeIcon() + '</div>' +
      '<div class="db">' +
        '<h2>' + esc(p.name) + '</h2>' +
        '<p style="font-size:15px;margin:8px 0 12px">This product is made up of ' + p.components.length + ' parts.</p>' +
        rows +
      '</div></aside>');
  }

  /* ---------- added-to-bag drawer ---------- */
  function addedPanel(o) {
    var p = P(o.id);
    if (!p) return '';
    var qty = o.qty || 1;
    var per = p.pack_size ? (', ' + p.pack_size + ' pack/pack') : '';
    var likes = (o.likes || []).map(function (id) { return P(id); }).filter(Boolean);
    var likeRows = likes.map(function (l) {
      var off = l.regular_price > l.member_price;
      return '<div class="like">' +
        '<img src="' + l.image + '">' +
        '<div>' + (off ? '<div class="fam">IKEA Family price</div>' : '') +
          '<div class="nm">' + esc(l.name) + '</div>' +
          '<div style="font-size:13px">' + esc(l.description) + (l.pack_size ? ', ' + l.pack_size + ' pack/pack' : '') + '</div>' +
          '<div class="pr">' + big(l.member_price) + '</div>' +
          (off ? '<div class="sv" style="color:var(--blue);font-weight:700;font-size:13px">' + pct(l) + '% off, save $' + saveAmt(l) + '</div>' +
            '<div style="font-size:12px;color:#484848">Regular price ' + money(l.regular_price) + '</div>' +
            '<div style="font-size:12px;color:#484848">Price valid Oct 7, 2026 - Nov 11, 2026 or while supply lasts</div>' : '') +
        '</div>' +
        '<div style="display:flex;flex-direction:column;gap:10px;align-items:center">' +
          '<button class="iconbtn" style="background:var(--blue);color:#fff;width:38px;height:38px" data-act="add-to-bag" data-id="' + l.id + '" data-qty="1" aria-label="Add to bag">' + I.cartW + '</button>' +
          '<button class="iconbtn" data-act="fav" aria-label="Save">' + I.heartOut + '</button>' +
        '</div></div>';
    }).join('');
    return ovWrap('<aside class="drawer wide added">' +
      '<div class="dh"><div></div>' + closeIcon() + '</div>' +
      '<div class="db">' +
        '<div class="item">' +
          '<img src="' + p.image + '">' +
          '<div><span class="ok" style="display:inline-flex;width:26px;height:26px;border-radius:50%;background:var(--green);color:#fff;align-items:center;justify-content:center;vertical-align:top">' + I.check + '</span>' +
            '<div style="display:inline-block;margin-left:12px;vertical-align:top">' +
              '<div style="font-weight:700">' + esc(p.name) + '</div>' +
              '<div style="font-size:14px">' + esc(p.description) + per + '</div></div></div>' +
          '<div style="font-weight:700">' + money(p.regular_price * qty) + '</div>' +
        '</div>' +
        '<p class="msg">' + qty + ' ' + esc(p.name) + ' were added to your shopping bag.</p>' +
        (likeRows ? '<div class="yl">You might also like</div>' + likeRows : '') +
        '<div class="ship">' + I.truck + '<span>Spend $15.00 more to enable delivery and other pick-up options. <a style="text-decoration:underline">Learn more</a></span></div>' +
      '</div>' +
      '<div class="df" style="display:flex;gap:12px">' +
        '<button class="btn ghost" style="flex:1" data-act="close-overlay">Continue shopping</button>' +
        '<button class="btn blue" style="flex:1" data-act="nav" data-href="#/bag">Go to shopping bag</button>' +
      '</div></aside>');
  }", "file_complete": false, "project_complete": false}
